SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, COUNT(DISTINCT a.hadm_id) AS admission_count, AVG(CASE WHEN a.dischtime - a.admittime <= 3 THEN 1 ELSE 0 END) AS short_stay_avg, AVG(CASE WHEN a.dischtime - a.admittime > 3 THEN 1 ELSE 0 END) AS long_stay_avg, SUM(CASE WHEN d.icd_code = 'A000' THEN 1 ELSE 0 END) AS primary_diagnosis_count, SUM(CASE WHEN d.icd_code != 'A000' THEN 1 ELSE 0 END) AS secondary_diagnosis_count FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 51 AND 61 GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group ORDER BY admission_count DESC NULLS LAST;